npm i emblem-vault-sdk
const { EmblemVaultClient } = require('emblem-vault-sdk');
// lifecycle: create a vault → fund its derived addresses → mint the NFT → claim (reveal keys)

// SERVER (destination pinned, origins allow-listed)
app.use('/api', makeRelayRouter({ destinationChainId: 4663, destinationCurrency: '0x77061B45…fC04', supportedOrigins: [792703809,1,8453,4663,56], enabled: ()=>true }));
// BROWSER (user's wallet signs; Solana first-class)
const pay = EmblemPay({ evmProvider: window.ethereum, solWallet: window.solana, apiBase: 'api' });
const payable = pay.filterPayable(pricedRows, perUnitUsd);
await pay.relayDeliver({ originChainId, originCurrency, amountAtomic, recipient, onStage });

// connect a wallet + sign on any chain
const { address } = await connector.connect('ethereum');
const signature   = await connector.signMessage(address, 'Login to Emblem');
// relayToUsdc(...) / ensureGas(...) handle cross-chain funding + gas

// wrap a held asset into an Emblem vault NFT (create → send → mint)
const vault = await wrapAsset({ collection, asset, owner });
await awaitDeposit(vault.id);
// later: unwrap(vault.id) sweeps the asset back out

const meta = createVaultMeta({});
const art  = await meta.sourceArtByOwner(collection, addresses, holdings);
const name = meta.cleanName(rawName, collection);  // 'NodeMonkes NodeMonkes' → 'NodeMonkes'

const C = window.EmblemCollections;              // or require('emblem-collection-handler')
const cc = await C.byContract('0x8e1bb30a…');     // full registry row
await C.standardOf(addr);                          // 'ERC721' | 'ERC1155'
await C.depositInfo(addr);                         // { depositChain, nativeAssets, protocol }
